function validate([towers, radius]) {
  if (!Array.isArray(towers) || towers.length < 1 || towers.length > 50) return 'towers needs 1 to 50 entries.';
  for (const tower of towers) {
    if (!Array.isArray(tower) || tower.length !== 3) return 'Each tower is [x, y, q].';
    if (tower.some(v => !Number.isInteger(v) || v < 0 || v > 50)) return 'Tower x, y and q are whole numbers from 0 to 50.';
  }
  if (!Number.isInteger(radius) || radius < 1 || radius > 50) return 'radius is between 1 and 50.';
  return null;
}

