function bestCoordinate(towers, radius) {
  let maxX = 0;
  let maxY = 0;
  for (const [x, y] of towers) {
    maxX = Math.max(maxX, x);
    maxY = Math.max(maxY, y);
  }

  let best = [0, 0];
  let bestQuality = 0;
  for (let cx = 0; cx <= maxX; cx++) {
    for (let cy = 0; cy <= maxY; cy++) {
      let quality = 0;
      for (const [x, y, q] of towers) {
        const squared = (x - cx) * (x - cx) + (y - cy) * (y - cy);
        if (squared <= radius * radius) {
          quality += Math.floor(q / (1 + Math.sqrt(squared)));
        }
      }
      if (quality > bestQuality) {
        bestQuality = quality;
        best = [cx, cy];
      }
    }
  }
  return best;
}

