function bestCoordinate(towers, radius) {
  // Score a wider square of points, then sort by quality (high first), x, then y.
  const scored = [];
  for (let px = 0; px <= 60; px++) {
    for (let py = 0; py <= 60; py++) {
      const total = towers.reduce((sum, [tx, ty, tq]) => {
        const dx = tx - px;
        const dy = ty - py;
        if (dx * dx + dy * dy > radius * radius) return sum;
        return sum + Math.floor(tq / (1 + Math.sqrt(dx * dx + dy * dy)));
      }, 0);
      scored.push([total, px, py]);
    }
  }
  scored.sort((a, b) => b[0] - a[0] || a[1] - b[1] || a[2] - b[2]);
  return [scored[0][1], scored[0][2]];
}

