function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = int(40, 50);
    const span = [10, 50][int(0, 1)];
    const towers = Array.from({ length: n }, () => [int(0, span), int(0, span), int(0, 50)]);
    return [towers, int(1, 50)];
  }
  const n = int(1, 6);
  const span = [3, 8, 50][int(0, 2)];
  const qualityCap = [1, 5, 50][int(0, 2)];
  const towers = Array.from({ length: n }, () => [int(0, span), int(0, span), int(0, qualityCap)]);
  return [towers, int(1, Math.min(50, span + 2))];
}
